/**
 * Packages the Chrome extension's recognition engine (MediaPipe HandLandmarker +
 * isl_mlp classifier + ISLCore feature maths) for the mobile WebView.
 *
 *   node scripts/build-engine.js
 *
 * Output:
 *   assets/engine/hand_landmarker.task          (Metro asset)
 *   assets/engine/vision_wasm_internal.wasm     (Metro asset)
 *   services/engine/engineBundle.generated.ts   (inlined JS + MLP weights)
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = path.resolve(__dirname, '..');
const ext = path.join(root, 'abhivyakta-extension');
const outAssets = path.join(root, 'assets', 'engine');
const outTs = path.join(root, 'services', 'engine', 'engineBundle.generated.ts');

fs.mkdirSync(outAssets, { recursive: true });
fs.mkdirSync(path.dirname(outTs), { recursive: true });

const copy = (from, to) => fs.copyFileSync(path.join(ext, from), path.join(outAssets, to));
copy('models/hand_landmarker.task', 'hand_landmarker.task');
copy('lib/wasm/vision_wasm_internal.wasm', 'vision_wasm_internal.wasm');

// MediaPipe bundle: ES module -> classic script exposing window.__MP
let bundle = fs.readFileSync(path.join(ext, 'lib', 'vision_bundle.mjs'), 'utf8');
bundle = bundle.replace(/\/\/# sourceMappingURL=.*$/m, '');
const exportRe = /export\s*\{[^}]*\}\s*;?/;
const m = bundle.match(exportRe);
if (!m) throw new Error('export clause not found in vision_bundle.mjs');
const names = {};
m[0].replace(/(\w+)\s+as\s+(\w+)/g, (_, local, exported) => { names[exported] = local; });
if (!names.HandLandmarker || !names.FilesetResolver) throw new Error('HandLandmarker export missing');
bundle = bundle.replace(exportRe, `window.__MP={HandLandmarker:${names.HandLandmarker},FilesetResolver:${names.FilesetResolver}};`);
new vm.Script(bundle); // must parse as a classic script (no top-level await / import.meta)
if (/<\/script/i.test(bundle)) bundle = bundle.replace(/<\/script/gi, '<\\/script');

const core = fs.readFileSync(path.join(ext, 'engine', 'isl-core.js'), 'utf8');
const loader = fs.readFileSync(path.join(ext, 'lib', 'wasm', 'vision_wasm_internal.js')).toString('base64');
const mlp = fs.readFileSync(path.join(ext, 'models', 'isl_mlp.bin')).toString('base64');
const meta = fs.readFileSync(path.join(ext, 'models', 'isl_meta.json'), 'utf8');
JSON.parse(meta);

const out =
  '/* AUTO-GENERATED by scripts/build-engine.js - do not edit. */\n' +
  `export const MP_BUNDLE_JS = ${JSON.stringify(bundle)};\n` +
  `export const ISL_CORE_JS = ${JSON.stringify(core)};\n` +
  `export const WASM_LOADER_B64 = ${JSON.stringify(loader)};\n` +
  `export const ISL_MLP_B64 = ${JSON.stringify(mlp)};\n` +
  `export const ISL_META_JSON = ${JSON.stringify(meta)};\n`;
fs.writeFileSync(outTs, out);
console.log('engine built:', (out.length / 1024).toFixed(0) + ' KB ts,', Object.keys(names).length, 'exports scanned');
